package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TlsClientAuthSubjectDnVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property tls client auth subject dn of trusted client ")
  void test_tls_client_auth_subject_dn_v_o_builder() {
    Assertions.assertFalse(
        TlsClientAuthSubjectDnVO.nullValue().getTlsClientAuthSubjectDn().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        TlsClientAuthSubjectDnVO.tryFrom(null).getTlsClientAuthSubjectDn().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        TlsClientAuthSubjectDnVO.from("one").getTlsClientAuthSubjectDn().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> TlsClientAuthSubjectDnVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", TlsClientAuthSubjectDnVO.from("one").toString());
  }
}
